@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@500;600;700;800&display=swap');

:root {
  color-scheme: light;
  --ink: #202335;
  --muted: #85899a;
  --line: #ececf1;
  --purple: #6254d8;
  --purple-dark: #5143c4;
  --canvas: #f7f8fb;
  --surface: #fff;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background: var(--canvas);
  color: var(--ink);
  font-family: 'DM Sans', sans-serif;
  font-size: 14px;
  -webkit-font-smoothing: antialiased;
}

button {
  font: inherit;
}

.catalog-page {
  min-height: 100vh;
}

.topbar {
  height: 72px;
  padding: 0 clamp(24px, 6.4vw, 104px);
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: var(--surface);
  border-bottom: 1px solid #eff0f4;
}

.breadcrumbs,
.account-chip {
  display: flex;
  align-items: center;
}

.breadcrumbs {
  gap: 13px;
  color: #9699a7;
  font-size: 13px;
}

.breadcrumb-divider {
  color: #c5c6ce;
}

.breadcrumb-current {
  color: #3b3e50;
  font-weight: 600;
}

.account-chip {
  gap: 10px;
  color: #494c5d;
  font-size: 13px;
  font-weight: 600;
}

.account-avatar {
  display: grid;
  width: 34px;
  height: 34px;
  place-items: center;
  border-radius: 50%;
  background: #e8e5ff;
  color: #5143c4;
  font-weight: 700;
}

.chevron-icon {
  width: 15px;
  fill: none;
  stroke: #979aaa;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.5;
}

.catalog-content {
  width: min(1120px, calc(100% - 48px));
  margin: 0 auto;
  padding: 48px 0 72px;
}

.page-heading {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 30px;
}

.eyebrow {
  margin: 0 0 10px;
  color: #8175dd;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
}

h1,
h2,
p {
  margin-top: 0;
}

h1,
h2,
.overview-value {
  font-family: 'Manrope', sans-serif;
}

h1 {
  margin-bottom: 7px;
  font-size: clamp(27px, 3vw, 34px);
  font-weight: 700;
  letter-spacing: -1.2px;
  line-height: 1.2;
}

.page-description {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
}

.sync-button {
  display: inline-flex;
  min-height: 44px;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 0 16px;
  border: 0;
  border-radius: 8px;
  background: var(--purple);
  box-shadow: 0 3px 7px rgb(98 84 216 / 16%);
  color: #fff;
  cursor: pointer;
  font-size: 13px;
  font-weight: 600;
  transition: background 140ms ease, transform 140ms ease;
}

.sync-button:hover {
  background: var(--purple-dark);
  transform: translateY(-1px);
}

.sync-button:focus-visible {
  outline: 3px solid #c8c2ff;
  outline-offset: 3px;
}

.sync-icon {
  width: 17px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.7;
}

.overview-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px;
  margin-bottom: 24px;
}

.overview-card {
  min-height: 142px;
  padding: 20px 22px;
  border: 1px solid #efeff4;
  border-radius: 11px;
  background: var(--surface);
  box-shadow: 0 2px 8px rgb(32 35 53 / 2%);
}

.overview-label {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #737789;
  font-size: 12px;
  font-weight: 500;
}

.overview-icon {
  display: grid;
  width: 32px;
  height: 32px;
  place-items: center;
  border-radius: 8px;
}

.overview-icon svg {
  width: 17px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 1.5;
}

.icon-lilac {
  background: #f0edff;
  color: #7163dc;
}

.icon-mint {
  background: #e9f8f2;
  color: #35a47c;
}

.icon-peach {
  background: #fff2e9;
  color: #de8c57;
}

.overview-value {
  margin: 9px 0 2px;
  font-size: 25px;
  font-weight: 700;
  letter-spacing: -0.7px;
  line-height: 1.2;
}

.overview-note {
  margin: 0;
  color: #999cab;
  font-size: 11px;
}

.catalog-panel {
  overflow: hidden;
  border: 1px solid #efeff4;
  border-radius: 11px;
  background: var(--surface);
  box-shadow: 0 2px 8px rgb(32 35 53 / 2%);
}

.panel-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 22px 24px 20px;
}

.panel-heading h2 {
  margin: 0 0 4px;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: -0.25px;
}

.panel-heading p {
  margin: 0;
  color: #9296a5;
  font-size: 12px;
}

.product-count {
  padding: 6px 9px;
  border-radius: 6px;
  background: #f5f4ff;
  color: #6d61d1;
  font-size: 11px;
  font-weight: 600;
}

.table-scroll {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
}

thead {
  background: #fafafd;
}

th {
  height: 42px;
  padding: 0 24px;
  border-top: 1px solid #f0f0f4;
  border-bottom: 1px solid #f0f0f4;
  color: #9296a5;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.35px;
  text-transform: uppercase;
}

td {
  height: 68px;
  padding: 0 24px;
  border-bottom: 1px solid #f1f1f5;
  color: #686c7d;
  font-size: 12px;
}

tbody tr:last-child td {
  border-bottom: 0;
}

.product-cell {
  display: flex;
  align-items: center;
  gap: 12px;
}

.product-avatar {
  display: grid;
  width: 37px;
  height: 37px;
  flex: 0 0 37px;
  place-items: center;
  border-radius: 9px;
  font-family: 'Manrope', sans-serif;
  font-size: 15px;
  font-weight: 700;
}

.tone-1 {
  background: #eeeaff;
  color: #7062d9;
}

.tone-2 {
  background: #e9f5ff;
  color: #4289bd;
}

.tone-3 {
  background: #e9f7ef;
  color: #45a071;
}

.tone-4 {
  background: #fff1e8;
  color: #d7834d;
}

.tone-5 {
  background: #fceaf1;
  color: #c65b86;
}

.product-name {
  color: #333648;
  font-size: 13px;
  font-weight: 600;
}

.product-id {
  color: #9296a5;
  font-variant-numeric: tabular-nums;
}

.price-column {
  text-align: right;
}

.product-price {
  color: #343749;
  font-size: 13px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}

.panel-footer {
  display: flex;
  min-height: 49px;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 0 24px;
  border-top: 1px solid #f0f0f4;
  color: #9a9dab;
  font-size: 11px;
}

.cache-indicator {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  color: #777b8b;
}

.cache-indicator span {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #4cbd8e;
  box-shadow: 0 0 0 3px #e8f7f0;
}

@media (max-width: 700px) {
  .topbar {
    height: 62px;
    padding: 0 20px;
  }

  .account-name,
  .chevron-icon {
    display: none;
  }

  .catalog-content {
    width: min(100% - 32px, 540px);
    padding-top: 34px;
  }

  .page-heading {
    align-items: flex-start;
    flex-direction: column;
    margin-bottom: 23px;
  }

  .overview-grid {
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .overview-card {
    min-height: 116px;
    padding: 16px 18px;
  }

  .overview-value {
    font-size: 23px;
  }

  .panel-heading {
    padding: 18px 16px;
  }

  th,
  td {
    padding-right: 16px;
    padding-left: 16px;
  }

  th:first-child,
  td:first-child {
    padding-left: 18px;
  }

  .panel-footer {
    align-items: flex-start;
    flex-direction: column;
    justify-content: center;
    gap: 8px;
    padding: 12px 18px;
  }
}
